import { MeterBarChartThresholdProps } from '../types/meter-bar-chart.js';

export const findMatchingThreshold = (
  value: number,
  thresholdData: MeterBarChartThresholdProps[],
  min: number,
): MeterBarChartThresholdProps | undefined =>
  [...thresholdData]
    .sort((a, b) => b.value - a.value)
    .find((threshold) => value + min >= threshold.value);
